<script setup lang="ts">
import {ref,computed,onMounted,watch,onBeforeUnmount} from 'vue'
import {LayoutDashboard,NotebookPen,CloudUpload,Wallet,Boxes,ScrollText,LogOut,RefreshCw,Plus,Search,Pencil,Trash2,RotateCcw,Sun,Sunset,Sprout,WifiOff,CheckCircle2,ChevronRight,Menu,X} from 'lucide-vue-next'
import {useRegisterSW} from 'virtual:pwa-register/vue'
import {prepareOfflineShell} from './offline-shell'
import {session,boot,records,queue,online,reachable,syncing,syncError,pendingCount,conflictCount,initialize,refresh,login,logout,localDate,submit,api,synchronize,db,activeRule} from './data'
import type {Harvest,Operation,Pending} from './types'
import Dashboard from './components/Dashboard.vue'
import RecordEditor from './components/RecordEditor.vue'
import SyncCenter from './components/SyncCenter.vue'
import CatalogPage from './components/CatalogPage.vue'
import PayrollPage from './components/PayrollPage.vue'
import DailyReviewPage from './components/DailyReviewPage.vue'
import DataList from './components/DataList.vue'
import ImportPage from './components/ImportPage.vue'
import PlotCostsPage from './components/PlotCostsPage.vue'
const page=ref('dashboard'),month=ref(localDate().slice(0,7)),error=ref(''),toast=ref(''),loading=ref(false),username=ref('admin'),password=ref(''),logging=ref(false)
let toastTimer:ReturnType<typeof setTimeout>|undefined
function clearToast(){if(toastTimer!==undefined)clearTimeout(toastTimer);toastTimer=undefined;toast.value=''}
function showToast(message:string){clearToast();toast.value=message;toastTimer=setTimeout(clearToast,3000)}
const editing=ref(false),selected=ref<Harvest|null>(null),preserved=ref<Operation|null>(null),conflictId=ref<string|undefined>(),menu=ref(false),query=ref(''),period=ref('ALL'),showDeleted=ref(false),logs=ref<any[]>([]),auditDetail=ref<any|null>(null)
const entryMode=ref<'ADD'|'CORRECT'|'MOVE'>('ADD'),continuous=ref(false),filterGroup=ref('*'),fromDate=ref(''),toDate=ref(''),filterProduct=ref(''),ledgerList=ref<any>(null),historyRows=ref<any[]|null>(null),historyId=ref('')
async function history(r:Harvest){historyId.value=r.id;try{historyRows.value=await api('/records/'+r.id+'/history')}catch(e){error.value=(e as Error).message}}
function auditQuantity(raw:string){const row=JSON.parse(raw);if(!row?.inputs_json)return '首次登记';const input=JSON.parse(row.inputs_json);const rule=activeRule(row.product_id,row.work_date);const unit=input.weightUnit==='jin'?'斤':input.weightUnit==='g'?'克':'公斤';return input.totalWeight!=null?input.totalWeight+' '+unit:Object.entries(input.quantities||{}).map(([key,value])=>{const stage=rule?.stages.find(s=>s.key===key);return (stage?.label||'工作量')+'：'+value+' '+(stage?.type==='PIECE'?'筐':unit)}).join(' / ')}
function increase(r:Harvest){edit(r);entryMode.value='ADD'}
function startContinuous(){create();continuous.value=true}
const autoConflict=ref<Pending|null>(null)
const operating=ref<string|null>(null)
const notifiedConflicts=new Set<string>()
watch(queue,(items)=>{const item=items.find(q=>q.result?.status==='VERSION_CONFLICT'&&!notifiedConflicts.has(q.operationId));if(item&&!autoConflict.value){notifiedConflicts.add(item.operationId);autoConflict.value=item}})
function resolveVersion(keepInput:boolean){const q=autoConflict.value;if(!q?.result?.record)return;autoConflict.value=null;page.value='sync';edit(q.result.record,keepInput?q.operation:null,q.operationId)}
const isAdmin=computed(()=>session.value?.user.role==='ADMIN')
const navigation=computed(()=>[{key:'dashboard',name:'农场概览',icon:LayoutDashboard},{key:'records',name:'采摘账本',icon:NotebookPen},{key:'sync',name:'同步中心',icon:CloudUpload},{key:'daily',name:'每日核对',icon:NotebookPen},{key:'plots',name:'地块人工成本',icon:LayoutDashboard},{key:'imports',name:'资料批量导入',icon:Boxes},{key:'weights',name:'重量配置',icon:Boxes},...(isAdmin.value?[{key:'payroll',name:'月度工资',icon:Wallet},{key:'catalog',name:'基础资料',icon:Boxes},{key:'audit',name:'操作日志',icon:ScrollText}]:[])])
const visible=computed(()=>records.value.filter(r=>(showDeleted.value||!r.deleted)&&(filterGroup.value==='*'||(r.groups?.length?r.groups.some(g=>g.group_id===filterGroup.value):filterGroup.value===''))&&(!fromDate.value||r.work_date>=fromDate.value)&&(!toDate.value||r.work_date<=toDate.value)&&(!filterProduct.value||r.product_id===filterProduct.value)&&(period.value==='ALL'||r.period===period.value)&&(!query.value||(r.worker_name+r.worker_code+r.product_name).toLocaleLowerCase().includes(query.value.toLocaleLowerCase()))))
const localRows=computed(()=>queue.value.filter(q=>q.operation.workDate.startsWith(month.value)))
const shellReady=ref(false)
const {offlineReady:cachedShell,needRefresh,updateServiceWorker}=useRegisterSW({immediate:true,onRegisteredSW(){void prepareOfflineShell(import.meta.env.DEV).then(()=>{shellReady.value=true}).catch(e=>{error.value='离线页面缓存未完成：'+String(e)})},onRegisterError(e){error.value='离线页面缓存未完成：'+String(e)}})
const offlineReady=computed(()=>shellReady.value&&(cachedShell.value||!!navigator.serviceWorker.controller))
async function reload(){if(!session.value)return;loading.value=true;error.value='';try{await refresh(month.value);if(page.value==='audit'&&isAdmin.value)logs.value=await api('/audit')}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
async function signIn(){logging.value=true;error.value='';try{await login(username.value,password.value);await initialize(month.value);password.value='';page.value='dashboard'}catch(e){error.value=(e as Error).message}finally{logging.value=false}}
function go(key:string){page.value=key;menu.value=false;error.value='';if(key==='audit'||key==='records')void reload()}
function create(){entryMode.value='ADD';continuous.value=false;if(!boot.value){error.value='请先联网下载基础资料';return}selected.value=null;preserved.value=null;conflictId.value=undefined;editing.value=true}
function edit(r:Harvest|null,p:Operation|null=null,cid?:string){entryMode.value=p?.entry?.mode||'CORRECT';continuous.value=false;selected.value=r;preserved.value=p;conflictId.value=cid;editing.value=true}
async function saved(message:string,keepOpen=false){if(!keepOpen)editing.value=false;showToast(message);await reloadCached()}
async function reloadCached(){if(!session.value)return;const cached=await db.cache.get(session.value.user.id+':records:'+month.value);if(cached)records.value=cached.value as Harvest[]}
async function operate(r:Harvest,action:'DELETE'|'RESTORE'){
  if(operating.value)return
  if(action==='DELETE'&&!canDelete(r)){error.value=deleteBlockedReason(r);return}
  if(!confirm(action==='DELETE'?'删除这条记录？日志仍会保留，误删可以恢复。':'恢复原记录？'))return
  operating.value=r.id;error.value='';clearToast()
  try{const message=await submit({operationId:crypto.randomUUID(),action,recordId:r.id,workerId:r.worker_id,workDate:r.work_date,period:r.period,productId:r.product_id,inputs:JSON.parse(r.inputs_json),note:r.note,version:r.version,reason:action==='DELETE'?'删除误记记录':'恢复误删记录'});showToast(message)}catch(e){error.value=(e as Error).message}finally{operating.value=null;await reloadCached()}
}
function canEdit(r:Harvest){return !r.deleted}
function canRestore(r:Harvest){return isAdmin.value||(!r.settled&&(r.work_date===localDate()||r.created_by===session.value?.user.id))}
function deleteBlockedReason(r:Harvest){if(r.settled)return '该记录已纳入确认结算，不能直接删除，请通过更正数量处理，原账目快照保留';return isAdmin.value||r.created_by===session.value?.user.id?'':'仅可删除自己录入的未结算记录'}
function canDelete(r:Harvest){return !deleteBlockedReason(r)}
async function signOut(){if((queue.value.length)&&!confirm('本机还有未处理操作。退出后仍归原账号保留，重新登录原账号才能继续同步。确认退出？'))return;menu.value=false;editing.value=false;selected.value=null;preserved.value=null;conflictId.value=undefined;autoConflict.value=null;auditDetail.value=null;historyRows.value=null;logs.value=[];clearToast();error.value='';password.value='';notifiedConflicts.clear();page.value='dashboard';await logout()}
const actionNames:Record<string,string>={ADD_QUANTITY:'增加采摘量',CORRECT_QUANTITY:'更正数量',DAILY_SIGN:'登记纸表签字',PRINT_TEMPLATE:'调整打印模板',SAVE_GROUPS:'维护班组',SAVE_BASKETS:'维护筐型',CREATE:'新增记录',UPDATE:'修改记录',DELETE:'删除记录',RESTORE:'恢复记录',SETTLE:'确认月结',SUPPLEMENT:'确认补结算',PAYMENT:'登记付款',PUBLISH_RULE:'发布计费规则',SAVE_WORKERS:'维护工人',SAVE_PRODUCTS:'维护产品',SAVE_CATEGORIES:'维护类别',SAVE_USERS:'维护账号',SAVE_GROSSWEIGHTS:'维护毛重配置',PAYROLL_SNAPSHOT:'付款时保存账目快照',DEMO_INIT:'初始化演示资料'}
async function synced(){await reloadCached();if(navigator.onLine)await reload()}
onMounted(async()=>{await initialize(month.value);window.addEventListener('farm-synced',synced)})
onBeforeUnmount(()=>{window.removeEventListener('farm-synced',synced);clearToast()})
watch(month,async()=>{await initialize(month.value)})
watch(isAdmin,(v)=>{if(!v&&!['dashboard','records','sync','daily'].includes(page.value))page.value='dashboard'})
</script>
<template>
  <div v-if="!session||logging" class="login-layout"><section class="login-story"><a class="brand" href="/"><img src="/farm.svg" alt=""/><span>田间账本<small>HARVEST LEDGER</small></span></a><p class="eyebrow">农场采摘计件计重管理系统</p><h1>每一筐收获，<br/>每一份辛劳。<br/><em>都值得记清楚。</em></h1><p>田间离线记，联网自动传，月底清楚算。</p><div class="login-field" aria-hidden="true"><Sprout :size="180" :stroke-width="1"/><div></div></div><small>Spring Boot + Vue · 本地演示版</small></section><section class="login-form"><div><span class="tag">欢迎回来</span><h2>登录你的农场账本</h2><p class="muted">首次使用请保持联网，完成资料准备。</p><form @submit.prevent="signIn"><label>账号<input v-model="username" autocomplete="username" required placeholder="请输入账号"/></label><label>密码<input v-model="password" type="password" autocomplete="current-password" required placeholder="请输入密码"/></label><p v-if="error" class="notice danger" role="alert">{{error}}</p><button class="primary login-submit" :disabled="logging">{{logging?'正在登录…':'登录账本'}}<ChevronRight :size="18"/></button></form><details class="demo-accounts"><summary>本地演示账号</summary><p>老板：admin<br/>记录员：recorder / recorder2<br/>初始密码：Farm@2026</p></details></div></section></div>
  <div v-else class="app-layout"><aside class="sidebar" :class="{open:menu}"><a href="#" class="brand" @click.prevent="go('dashboard')"><img src="/farm.svg" alt=""/><span>田间账本<small>HARVEST LEDGER</small></span></a><p class="sidebar-label">农场工作台</p><nav><button v-for="n in navigation" :key="n.key" :class="{active:page===n.key}" @click="go(n.key)"><component :is="n.icon" :size="19"/><span>{{n.name}}</span><span v-if="n.key==='sync'&&(queue.length)" class="nav-count">{{queue.length}}</span></button></nav><div class="sidebar-bottom"><div class="farm-label"><Sprout :size="20"/><div><strong>单基地 · 农场演示</strong><small>让每一笔劳动有据可查</small></div></div><button @click="signOut"><LogOut :size="17"/>退出登录</button></div></aside><button v-if="menu" class="menu-backdrop" aria-label="收起导航" @click="menu=false"/>
    <div class="workspace"><header class="topbar"><div class="breadcrumbs"><button class="mobile-menu icon-button" aria-label="打开导航" @click="menu=!menu"><Menu/></button><span>农场工作台</span><ChevronRight :size="14"/><strong>{{navigation.find(n=>n.key===page)?.name}}</strong></div><div class="topbar-right"><span class="connection" :class="{'offline':!online||!reachable}"><span></span>{{!online?'离线模式':!reachable?'后台暂不可达':'网络正常'}}</span><div class="user-chip"><span class="avatar">{{session.user.name.slice(-1)}}</span><div><strong>{{session.user.name}}</strong><small>{{isAdmin?'管理员':'记录员'}}</small></div></div><button class="header-logout" @click="signOut"><LogOut :size="17"/><span>退出登录</span></button></div></header>
      <div v-if="!online||!reachable" class="offline-banner" role="status"><WifiOff :size="18"/><span>{{!online?'当前网络异常，已切换至离线模式。':'暂时无法连接后台，记录将保存在本机。'}} {{pendingCount}} 项待同步。</span><button @click="go('sync')">查看队列</button></div>
      <div v-if="needRefresh" class="update-banner"><span>有新版本可用，本机未同步数据会保留。</span><button :disabled="!!queue.length" @click="updateServiceWorker()">{{queue.length?'请先处理待同步记录':'更新页面'}}</button></div>
      <main><div class="workspace-controls"><span class="season-label"><Sprout :size="16"/>农场采摘 · 工作账本</span><div class="button-row"><label class="month-control"><span>账本月份</span><input v-model="month" type="month" required/></label><button class="icon-button" :disabled="loading" aria-label="刷新数据" @click="reload"><RefreshCw :size="18" :class="{spin:loading}"/></button></div></div>
        <p v-if="error" class="notice danger" role="alert">{{error}}</p>
        <Dashboard v-if="page==='dashboard'" :month="month" @navigate="go" @create="create"/>
        <template v-if="page==='records'"><div class="page-intro"><div><p class="eyebrow">按日、按时段，记清每笔工作量</p><h1>采摘账本</h1><p class="muted">同一工人、日期、时段和产品只保留一条记录。</p></div><div class="button-row"><button @click="startContinuous">连续录入</button><button class="primary" @click="create"><Plus :size="18"/>记一笔采摘</button></div></div><div class="ledger-toolbar"><label class="search-box"><Search :size="18"/><input v-model="query" placeholder="查找工人、工号或产品" aria-label="搜索采摘记录"/></label><div class="segmented"><button :class="{selected:period==='ALL'}" @click="period='ALL'">全部时段</button><button :class="{selected:period==='AM'}" @click="period='AM'"><Sun :size="16"/>上午</button><button :class="{selected:period==='PM'}" @click="period='PM'"><Sunset :size="16"/>下午</button></div><label>班组<select v-model="filterGroup"><option value="*">全部班组</option><option value="">未分组</option><option v-for="g in boot?.groups" :key="g.id" :value="g.id">{{g.name}}</option></select></label><label>开始日期<input v-model="fromDate" type="date" aria-label="采摘开始日期"/></label><label>结束日期<input v-model="toDate" type="date" aria-label="采摘结束日期"/></label><label>产品<select v-model="filterProduct" aria-label="查询产品"><option value="">全部产品</option><option v-for="p in boot?.products" :key="p.id" :value="p.id">{{p.name}}</option></select></label><button @click="ledgerList?.reload()">查询</button><button @click="query='';period='ALL';filterGroup='*';filterProduct='';fromDate='';toDate='';showDeleted=false">重置</button><label class="check-label"><input v-model="showDeleted" type="checkbox"/>含已删除</label></div>
        <div v-if="localRows.length" class="notice"><CloudUpload :size="18"/><span>本机还有 {{localRows.length}} 项操作待处理，以下后台账本尚未全部包含。</span><button class="compact" @click="go('sync')">查看本机记录</button></div>
        <DataList ref="ledgerList" :endpoint="'/query/records'" :params="{month,q:query,from:fromDate,to:toDate,productId:filterProduct,period:period==='ALL'?'':period,groupId:filterGroup,deleted:showDeleted}" :rows="visible" :show-search="false" scope="采摘账本" v-slot="{items}"><section class="panel table-wrap ledger-table"><table><thead><tr><th>工人 / 工号</th><th>采摘日期</th><th>时段</th><th>产品</th><th>工作量</th><th class="numeric">核算工资</th><th>最近修改</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="r in items" :key="r.id" :class="{deleted:r.deleted}"><td><strong>{{r.worker_name}}</strong><small>{{r.worker_code}}</small></td><td>{{r.work_date}}<small v-if="r.note" :title="r.note" class="note-preview">{{r.note}}</small></td><td><span class="period-label"><Sun v-if="r.period==='AM'" :size="15"/><Sunset v-else :size="15"/>{{r.period==='AM'?'上午':'下午'}}</span></td><td>{{r.product_name}}<small v-for="g in r.groups" :key="g.group_id">{{g.group_name}}</small><small v-if="!r.groups?.length">未分组</small><small v-for="a in r.allocations" :key="a.group_id+a.plot_id">{{a.group_name}} · {{a.plot_name}}</small></td><td><template v-if="r.quote?.parts.length"><span v-for="(p,i) in r.quote.parts" :key="i" class="quantity-line">{{p.quantity}} {{p.type==='PIECE'?'筐':'公斤'}}<small v-if="r.quote.parts.length>1">{{p.label}}</small></span></template><span v-else>—</span></td><td class="numeric amount">{{r.pricing_error?'待核对':'¥ '+Number(r.quote?.amount||0).toFixed(2)}}</td><td>{{r.updated_name}}<small>版本 {{r.version}}</small></td><td><span class="tag" :class="r.deleted?'neutral':r.pricing_error?'error':'good'">{{r.deleted?'已删除':r.pricing_error?'计价异常':r.settled?'已结算':'未结算'}}</span></td><td><div class="button-row"><button v-if="!r.deleted&&canEdit(r)" class="compact" @click="increase(r)">增加采摘量</button><button v-if="!r.deleted" class="compact" @click="edit(r);entryMode='MOVE'">更正地块</button><button class="compact" @click="history(r)">修改记录</button><button v-if="!r.deleted&&canEdit(r)" class="icon-button" :aria-label="r.settled?'更正已结算记录':'编辑数量'" @click="edit(r)"><Pencil :size="16"/><span>更正数量</span></button><button v-if="!r.deleted" class="compact text-danger delete-record" aria-label="删除记录" :disabled="!!operating||!canDelete(r)||queue.some(q=>q.operation.recordId===r.id)" :title="!canDelete(r)?deleteBlockedReason(r):queue.some(q=>q.operation.recordId===r.id)?'请先同步或处理这条记录的本机操作':'删除这条采摘记录'" @click="operate(r,'DELETE')"><Trash2 :size="16"/><span>删除</span></button><button v-if="r.deleted&&canRestore(r)" :disabled="!!operating||queue.some(q=>q.operation.recordId===r.id)" class="compact" @click="operate(r,'RESTORE')"><RotateCcw :size="15"/>恢复</button></div></td></tr></tbody></table><div v-if="!visible.length" class="empty"><NotebookPen :size="36"/><h3>还没有符合条件的记录</h3><p>调整筛选，或记录一笔新的采摘。</p><button @click="create">记一笔采摘</button></div></section></DataList></template>
        <p v-if="page==='sync'&&0" class="notice">还有 {{0}} 笔本机派工操作，请到<button @click="go('dispatch')">每日派工</button>核对处理。</p><SyncCenter v-if="page==='sync'" @edit="edit" @changed="reloadCached"/>
        <DailyReviewPage v-if="page==='daily'"/>
        <CatalogPage v-if="page==='weights'" :month="month" weights-only/>
        <ImportPage v-if="page==='imports'" :month="month"/>
        <PlotCostsPage v-if="page==='plots'" :month="month"/>
        <PayrollPage v-if="page==='payroll'&&isAdmin" :month="month"/>
        <CatalogPage v-if="page==='catalog'&&isAdmin" :month="month"/>
        <template v-if="page==='audit'&&isAdmin"><div class="page-intro"><div><p class="eyebrow">每一次变动，都留有记录</p><h1>操作日志</h1><p class="muted">显示最近 500 次业务操作，包含操作者、时间和前后数据。</p></div></div><DataList endpoint="/query/audit" :rows="logs" scope="操作日志" v-slot="{items}"><section class="panel table-wrap"><table><thead><tr><th>操作时间</th><th>操作人</th><th>行为</th><th>原因</th><th>明细</th></tr></thead><tbody><tr v-for="l in items" :key="l.id"><td>{{l.created_at}}</td><td>{{l.actor_name}}</td><td>{{actionNames[l.action]||l.action}}</td><td>{{l.reason||'—'}}</td><td><button class="compact" @click="auditDetail=l">查看前后值</button></td></tr></tbody></table><div v-if="!logs.length" class="empty">暂无操作日志。</div></section></DataList></template>
        <footer class="page-footer"><span>田间账本 · 农场采摘计件计重管理</span><span><CheckCircle2 :size="14"/>{{offlineReady?'离线页面已准备':'离线能力请先联网准备并验证'}}</span></footer>
      </main></div><nav class="bottom-nav"><button v-for="n in navigation.slice(0,isAdmin?5:4)" :key="n.key" :class="{active:page===n.key}" @click="go(n.key)"><component :is="n.icon" :size="20"/><span>{{n.name}}</span><b v-if="n.key==='sync'&&(queue.length)">{{queue.length}}</b></button></nav>
  </div>
  <RecordEditor v-if="editing" :record="selected" :preserved="preserved" :conflict-id="conflictId" :mode="entryMode" :continuous="continuous" @close="editing=false" @saved="saved"/>
  <div v-if="autoConflict" class="modal-shade"><section class="modal" role="alertdialog" aria-modal="true" aria-labelledby="version-conflict-title"><div class="modal-head"><h2 id="version-conflict-title">记录已被更新</h2><button class="icon-button" aria-label="稍后处理" @click="autoConflict=null"><X/></button></div><p>该记录已被【{{autoConflict.result?.record?.updated_name}}】更新，当前最新数量为 <strong>{{autoConflict.result?.record?.quote?.parts.map(p=>`${p.quantity}${p.type==='PIECE'?'筐':'公斤'}`).join(' / ')}}</strong>。</p><p>你填写的 <strong>{{Object.values(autoConflict.operation.inputs.quantities).join(' / ')||autoConflict.operation.inputs.totalWeight}}</strong> 已保存在本机，请核对后再次提交。</p><p class="muted">再次提交仍检查最新版本；选择稍后处理也不会丢失输入。</p><div class="modal-actions"><button @click="resolveVersion(false)">以最新数量重新修改</button><button class="primary" @click="resolveVersion(true)">保留我的输入，核对后重提</button></div></section></div>
  <div v-if="historyRows" class="modal-shade" @click.self="historyRows=null"><section class="modal wide-modal" role="dialog" aria-modal="true" aria-label="数量修改记录"><div class="modal-head"><h2>数量修改记录</h2><button class="icon-button" aria-label="关闭" @click="historyRows=null"><X/></button></div><DataList endpoint="/query/history" :params="{recordId:historyId}" :rows="historyRows" scope="数量修改记录" v-slot="{items}"><div v-for="l in items" :key="l.id" class="history-item"><strong>{{actionNames[l.action]||l.action}} · {{l.actor_name}}</strong><small>{{l.created_at}}</small><p>{{l.reason||'—'}}</p><p v-if="JSON.parse(l.after_json)?.quantity_operation">班组：{{boot?.groups?.find(g=>g.id===JSON.parse(l.after_json).quantity_operation.groupId)?.name||'未分组'}}</p><div class="form-grid"><div><h3>修改前数量</h3><pre>{{auditQuantity(l.before_json)}}</pre></div><div><h3>修改后数量</h3><pre>{{auditQuantity(l.after_json)}}</pre></div></div></div></DataList><p v-if="!historyRows.length">暂无修改记录。</p></section></div>
  <div v-if="auditDetail" class="modal-shade" @click.self="auditDetail=null"><section class="modal wide-modal" role="dialog" aria-modal="true" aria-label="操作前后数据"><div class="modal-head"><h2>{{actionNames[auditDetail.action]||auditDetail.action}}</h2><button class="icon-button" aria-label="关闭" @click="auditDetail=null"><X/></button></div><p>{{auditDetail.actor_name}} · {{auditDetail.created_at}}</p><h3>操作前</h3><pre>{{JSON.stringify(JSON.parse(auditDetail.before_json),null,2)}}</pre><h3>操作后</h3><pre>{{JSON.stringify(JSON.parse(auditDetail.after_json),null,2)}}</pre></section></div>
  <div v-if="toast" class="toast" role="status"><CheckCircle2 :size="20"/>{{toast}}</div>
</template>
